// Exception status and result bits of VALU conversions captured on a physical
// RX 9070 XT (gfx1201) on 2026-09-29 with ROCm 7.1.0. Each row executed exactly
// one instruction with traps disabled and read HW_REG_WAVE_EXCP_FLAG_USER
// (TRAPSTS[6:0] layout) before and after it. Distilled from the full capture
// (95,073 rows, sha256 57e54a2eba9168733c0ee9128d9d3088e26743ae5c3c75b6913a55dc4e32b512):
// the first capture of every behaviour class, keyed by variant, conversion
// facts of the participating lanes, raised causes and single-lane or wave row.
// See README.md.
#pragma once

#include <array>
#include <cstdint>

enum class CvtOp : uint8_t {
  kCvtF16F32,
  kCvtF16I16,
  kCvtF16U16,
  kCvtF32Bf8,
  kCvtF32F16,
  kCvtF32F64,
  kCvtF32Fp8,
  kCvtF32I32,
  kCvtF32U32,
  kCvtF64F32,
  kCvtF64I32,
  kCvtFloorI32F32,
  kCvtI16F16,
  kCvtI32F32,
  kCvtI32F64,
  kCvtNearestI32F32,
  kCvtPkBf8F32,
  kCvtPkFp8F32,
  kCvtPkNormI16F32,
  kCvtPkNormU16F32,
  kCvtPkRtzF16F32,
  kCvtSrBf8F32,
  kCvtSrFp8F32,
  kCvtU16F16,
  kCvtU32F32,
  kCvtU32F64
};

struct CvtStatusRow {
  CvtOp op;
  uint8_t vop3;
  uint8_t abs;
  uint8_t neg;
  uint8_t clamp;
  uint8_t omod;
  uint8_t op_sel; ///< VOP3 OP_SEL field: 0x8 selects the high word, 0xc byte 3.
  uint32_t mode;  ///< MODE[7:0] and FP16_OVFL (bit 23).
  uint32_t exec;  ///< Wave32 EXEC.
  uint8_t status_before;
  uint8_t status_after;
  uint64_t fill0; ///< Sources of every lane not listed separately.
  uint32_t fill1;
  uint64_t dst_init; ///< Destination before the instruction, in every lane.
  bool has_fill_result;
  uint64_t fill_result; ///< Destination of an active lane with the fill sources.
  uint16_t first_lane;
  uint16_t lane_count;
};

struct CvtStatusLane {
  uint8_t lane;
  uint64_t src0;
  uint32_t src1;
  uint64_t result; ///< Whole destination register(s), including preserved bits.
};

